import { expect, test } from "bun:test"
import type { CircuitJson } from "circuit-json"
import ddrFixture from "../fixtures/phase-skew/am3352-ddr-track-a.circuit.json"
import { renderCanvas } from "../fixtures/phase-skew/render-canvas"

// This is the AM3352 DDR fixture from tscircuit/pcb-viewer#1255, generated by
// tscircuit/compute-differential-pair-phase-skew#18. It retains the board,
// the three pad-to-pad skew records, their six traces, and their route vias.
const circuitJson = ddrFixture as CircuitJson

test("renders the fixed phase-skew scale on the three AM3352 DDR pairs", async () => {
  const { canvas, pixelAt } = renderCanvas({
    circuitJson,
    view: {
      width: 480,
      height: 1104,
      bounds: { minX: -5.2, maxX: 4.8, minY: -29, maxY: -5 },
    },
  })

  // Each pair has a fully saturated stretch at y = -15 mm.
  for (const x of [1.355, 3.704, -4.511]) {
    expect(pixelAt({ x, y: -15 })).toEqual([255, 0, 0, 255])
  }
  for (const x of [1.669, 3.478, -4.289]) {
    expect(pixelAt({ x, y: -15 })).toEqual([0, 0, 255, 255])
  }

  await expect(canvas.toBuffer("image/png")).toMatchPngSnapshot(
    import.meta.path,
  )
})
